(() => {
 const c=window.TOP_CONTENT;if(!c)return;
 const set=(selector,text)=>{const el=document.querySelector(selector);if(el)el.textContent=text;};
 set('.announcement .container>span:first-child',c.announcement);
 const title=document.querySelector('#hero-title');if(title){title.textContent=c.hero.title;title.style.whiteSpace='pre-line';set('.hero-copy>.eyebrow',c.hero.eyebrow);set('.hero-copy>p',c.hero.description);const button=document.querySelector('.hero-copy>.button');if(button)button.textContent=c.hero.button;if(c.hero.image){const panel=document.querySelector('.hero-brand');panel.textContent='';const img=document.createElement('img');img.src=c.hero.image;img.alt='';img.className='hero-photo';panel.append(img);}}
 const hero=document.querySelector('.hero');const banners=c.banners.filter(b=>b.active);if(hero&&banners.length){const section=document.createElement('section');section.className='container promotion-grid';section.setAttribute('aria-label','Destaques');banners.forEach(b=>{const card=document.createElement('article');card.className='promotion-card';if(b.image){const img=document.createElement('img');img.src=b.image;img.alt='';img.loading='lazy';card.append(img);}const body=document.createElement('div');const h=document.createElement('h2');h.textContent=b.title;const desc=document.createElement('p');desc.textContent=b.description;const a=document.createElement('a');a.className='button button-blue';a.href=b.href;a.textContent=b.button;body.append(h,desc,a);card.append(body);section.append(card);});hero.after(section);}
 if(!c.sampleCatalogue){document.querySelectorAll('.catalog-note,.catalog-section .sample-note').forEach(el=>el.hidden=true);}
 if(location.pathname.endsWith('/sobre.html')){const panel=document.querySelector('.content-panel');if(panel){panel.textContent='';const h=document.createElement('h2');h.textContent='Sobre nós';panel.append(h);c.about.split(/\n\s*\n/).forEach(s=>{const p=document.createElement('p');p.textContent=s;p.style.whiteSpace='pre-line';panel.append(p);});const a=document.createElement('a');a.className='button button-blue';a.href='https://wa.me/258837860064';a.textContent='Fale connosco no WhatsApp';panel.append(a);}}
})();
